        check(!prepared.phase(Phase.CANCELLED).pending(),"Proven unsubmitted cancellation releases town without paid effect");denied(()->prepared.phase(Phase.PAID).phase(Phase.CANCELLED),"Paid purchase cannot use unsubmitted cancellation");
