        var file=dir.resolve("data.yml");var core=new EspionageRepository(file,()->50,()->40,()->false,e->{throw new AssertionError(e);});core.load();var field=AtomicFiles.class.getDeclaredField("writers");field.setAccessible(true);@SuppressWarnings("unchecked")var locks=(Map<Path,ReentrantLock>)field.get(null);var lock=locks.computeIfAbsent(file.toAbsolutePath().normalize(),k->new ReentrantLock());lock.lock();CompletionStage<Void> pending;
